import{_ as a,c as r,o as i,b0 as t}from"./chunks/framework.Dmsv_Tiv.js";const A="data:image/bmp;base64,",o="/media-docs/assets/image-20240711074015102.C7kASKPV.png",n="/media-docs/assets/image-20241223080235580.Dllqh5PM.png",s="/media-docs/assets/2ac0f79cf9d2d91b293f305b4d4722d6._XewHjcc.jpeg",l="/media-docs/assets/ddbc363e1609b94d4253051becca44f4.DmeOySBE.jpeg",f=JSON.parse('{"title":"LV020-JPEG文件格式简介","description":null,"frontmatter":{"title":"LV020-JPEG文件格式简介","date":"2025-10-09T09:24:50.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/image/img-file-format/126b0e340b62052487c1efe0","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-10-09T09:24:50.082Z","fulluuid":"487c1efe0fc140b497ccb49844923176","useduuid":"487c1efe0"}},"headers":[],"relativePath":"sdoc/image/img-file-format/126b0e340b62052487c1efe0.md","filePath":"sdoc/01-图像/30-图像文件格式/LV020-JPEG文件格式简介.md","lastUpdated":1767537778000}'),E={name:"sdoc/image/img-file-format/126b0e340b62052487c1efe0.md"};function p(c,e,h,d,g,w){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="lv020-jpeg文件格式简介" tabindex="-1">LV020-JPEG文件格式简介 <a class="header-anchor" href="#lv020-jpeg文件格式简介" aria-label="Permalink to &quot;LV020-JPEG文件格式简介&quot;">​</a></h1><h2 id="一、静态图像数据量" tabindex="-1">一、静态图像数据量 <a class="header-anchor" href="#一、静态图像数据量" aria-label="Permalink to &quot;一、静态图像数据量&quot;">​</a></h2><p>上一节学习BMP图片格式的时候，做了这样一张BMP图：</p><img src="'+A+'" alt="format-30x13"><p>这个图片文件有1250个字节，我们使用画图工具另存一下，看看生成其他格式的图片会是怎样的：</p><img src="'+o+'" alt="image-20240711074015102" style="zoom:43%;"><p>可以看到生成其他格式之后，文件的体积都有不同程度的减小。那么这些都是通过什么途径来降低了静态图片的数据量的？</p><img src="'+n+'" alt="image-20241223080235580" style="zoom:80%;"><p>JPEG图片在平时是很常见的，接下来就来学习一下JPEG的相关内容。</p><h2 id="二、jpeg格式介绍" tabindex="-1">二、JPEG格式介绍 <a class="header-anchor" href="#二、jpeg格式介绍" aria-label="Permalink to &quot;二、JPEG格式介绍&quot;">​</a></h2><h3 id="_1-维基百科的简介" tabindex="-1">1. 维基百科的简介 <a class="header-anchor" href="#_1-维基百科的简介" aria-label="Permalink to &quot;1. 维基百科的简介&quot;">​</a></h3><p><strong><a href="https://www.wikiwand.com/zh-hans/JPEG" target="_blank" rel="noreferrer">JPEG</a></strong> 或称 <strong>JPG</strong>，是一种针对相片影像而广泛使用的<a href="https://www.wikiwand.com/zh-hans/%E6%9C%89%E6%8D%9F%E6%95%B0%E6%8D%AE%E5%8E%8B%E7%BC%A9" target="_blank" rel="noreferrer">失真压缩</a>标准方法，由<strong>联合图像专家小组</strong>（英语：<strong>J</strong>oint <strong>P</strong>hotographic <strong>E</strong>xperts <strong>G</strong>roup）开发。此团队创立于1986年，1992年发布了JPEG的标准而在1994年获得了ISO 10918-1的认定。JPEG与视讯音讯压缩标准的<a href="https://www.wikiwand.com/zh-hans/MPEG" target="_blank" rel="noreferrer">MPEG</a>（Moving Picture Experts Group）很容易混淆，但两者是不同的组织及标准。</p><p>JPEG本身只有描述如何将一个影像转换为<a href="https://www.wikiwand.com/zh-hans/%E5%AD%97%E8%8A%82" target="_blank" rel="noreferrer">字节</a>的数据串流（streaming），但并没有说明这些位元组如何在任何特定的储存媒体上受封存起来。JPEG的压缩方式通常是<a href="https://www.wikiwand.com/zh-hans/%E6%9C%89%E6%8D%9F%E5%8E%8B%E7%BC%A9" target="_blank" rel="noreferrer">有损压缩</a>，即在压缩过程中图像的品质会遭受到可见的破坏，有一种以JPEG为基础的标准<a href="https://www.wikiwand.com/zh-hans/Lossless_JPEG" target="_blank" rel="noreferrer">Lossless JPEG</a>是采用无失真的压缩方式，但Lossless JPEG并没有受到广泛的支援。</p><p>一个由C-Cube Microsystems等公司所建立的额外标准，称为<strong>JFIF</strong>（<strong>J</strong>PEG <strong>F</strong>ile <strong>I</strong>nterchange <strong>F</strong>ormat，JPEG档案交换格式，联合图像专家小组档案交换格式）详细说明如何从一个JPEG串流，产出一个适合于电脑储存和传输（像是在<a href="https://www.wikiwand.com/zh-hans/%E7%B6%B2%E9%9A%9B%E7%B6%B2%E8%B7%AF" target="_blank" rel="noreferrer">网际网路</a>上）的档案。在普遍的用法，当有人称呼一个&quot;JPEG档案&quot;，一般而言他是意指一个JFIF档案，或有时候是一个<a href="https://www.wikiwand.com/zh-hans/Exif" target="_blank" rel="noreferrer">Exif</a> JPEG档案。然而，也有其他以JPEG为基础的档案格式，像是<a href="https://www.wikiwand.com/zh-hans/JPEG_Network_Graphics" target="_blank" rel="noreferrer">JNG</a>。</p><p>使用JPEG格式压缩的图片档案一般也称为JPEG Files，最普遍使用的<a href="https://www.wikiwand.com/zh-hans/%E5%89%AF%E6%AA%94%E5%90%8D" target="_blank" rel="noreferrer">副档名</a>格式为.jpg，其他常用的<a href="https://www.wikiwand.com/zh-hans/%E5%89%AF%E6%AA%94%E5%90%8D" target="_blank" rel="noreferrer">副档名</a>还包括.JPEG、.jpe、.jfif以及.jif。JPEG格式的资料也能受嵌进其他类型的档案格式中，像是<a href="https://www.wikiwand.com/zh-hans/TIFF" target="_blank" rel="noreferrer">TIFF</a>类型的档案格式。</p><p>JPEG/JFIF是<a href="https://www.wikiwand.com/zh-hans/%E5%85%A8%E7%90%83%E8%B3%87%E8%A8%8A%E7%B6%B2" target="_blank" rel="noreferrer">全球资讯网</a>上最普遍的用来储存和传输照片的格式。它并<strong>不</strong>适合于线条绘图（drawing）和其他文字或<a href="https://www.wikiwand.com/zh-hans/%E5%9C%96%E7%A4%BA" target="_blank" rel="noreferrer">图示</a>（iconic）的图形，因为它的压缩方法用在这些类型的图形上，得到的结果并不好（<a href="https://www.wikiwand.com/zh-hans/PNG" target="_blank" rel="noreferrer">PNG</a>和<a href="https://www.wikiwand.com/zh-hans/GIF" target="_blank" rel="noreferrer">GIF</a>通常是用来存储这类的图形；GIF每个<a href="https://www.wikiwand.com/zh-hans/%E5%83%8F%E7%B4%A0" target="_blank" rel="noreferrer">像素</a>只有8<a href="https://www.wikiwand.com/zh-hans/%E4%BD%8D%E5%85%83" target="_blank" rel="noreferrer">位元</a>，并不很适合于存储彩色照片，PNG可以无失真地储存照片，但是档案太大的缺点让它不太适合在网路上传输）。</p><p>对于JFIF的<a href="https://www.wikiwand.com/zh-hans/MIME" target="_blank" rel="noreferrer">MIME</a>媒体类型是<em>image/JPEG</em>（定义于<a href="https://tools.ietf.org/html/rfc1341" target="_blank" rel="noreferrer">RFC 1341</a>）。</p><h3 id="_2-后缀名" tabindex="-1">2. 后缀名？ <a class="header-anchor" href="#_2-后缀名" aria-label="Permalink to &quot;2. 后缀名？&quot;">​</a></h3><p>前面已经说过了，JPEG（Joint Photographic Experts Group）是JPEG标准的产物，该标准由国际标准化组织（ISO）制订，是面向连续色调静止图像的一种压缩标准，是24位的图像文件格式。JPEG格式是最常用的图像文件格式，后缀名通常为<code>.jpg</code>或<code>.jpeg</code>。</p><h3 id="_3-三种格式" tabindex="-1">3. 三种格式 <a class="header-anchor" href="#_3-三种格式" aria-label="Permalink to &quot;3. 三种格式&quot;">​</a></h3><p>JPEG格式可以分为标准JPEG、渐进式JPEG和JPEG2000三种格式。其中标准JPEG和渐进式JPEG均为有损压缩。</p><ul><li>标准JPEG</li></ul><p>只有图片完全被加载和读取完毕之后，才能看到图片的全貌；它是一种很灵活的图片压缩方式，用户可以在压缩比和图片品质之间进行权衡。不过，通常来讲，其压缩比在10:1到40:1之间，压缩比越大，品质就越差，压缩比越小，品质就越好。JPEG格式压缩的主要是高频信息，对色彩的信息保留较好，适合应用于互联网，可减少图像的传输时间，可以支持24bit真彩色，也普遍应用于需要连续色调的图像。JPEG由于可以提供有损压缩，因此压缩比可以达到其他传统压缩算法无法比拟的程度。其压缩模式有以下几种：顺序式编码（SequentialEncoding），递增式编码（ProgressiveEncoding），无失真编码（LosslessEncoding）和阶梯式编码（HierarchicalEncoding）。</p><ul><li>渐进式JPEG</li></ul><p>此类型在网页下载时，先呈现出图像的粗略外观后，再慢慢地呈现出具体细节的内容，而且存成渐进式JPG格式的文档比存成标准JPG格式的文档要来得小，所以如果要在网页上使用图像，可以多用这种格式。</p><ul><li>JPEG2000</li></ul><p>它是新一代的影像压缩法，压缩品质更高，并可改善在<a href="https://baike.baidu.com/item/%E6%97%A0%E7%BA%BF%E4%BC%A0%E8%BE%93/5127153?fromModule=lemma_inlink" target="_blank" rel="noreferrer">无线传输</a>时，常因信号不稳造成<a href="https://baike.baidu.com/item/%E9%A9%AC%E8%B5%9B%E5%85%8B%E7%8E%B0%E8%B1%A1/1180753?fromModule=lemma_inlink" target="_blank" rel="noreferrer">马赛克现象</a>及位置错乱的情况，改善传输的品质。另外，作为JPEG的升级版，JPEG2000的压缩率比标准JPEG高约30%，同时支持有损压缩和无损压缩。它还支持渐进式传输，即先传输图片的粗略轮廓，然后，逐步传输细节数据，使得图片由模糊到清晰逐步显示。</p><blockquote><p>说明：它使用了与标准的JPEG完全不同的技术</p><p>1、使用小波变换代替DCT变换，避免了分块导致的马赛克模糊</p><p>2、采用自适应算术编码</p><p>3、支持无损压缩存储</p><p>4、支持渐进式传输和显示</p><p>5、支持ROI</p><p>6、压缩率相比JPEG更高</p></blockquote><h2 id="四、jpeg编码" tabindex="-1">四、JPEG编码 <a class="header-anchor" href="#四、jpeg编码" aria-label="Permalink to &quot;四、JPEG编码&quot;">​</a></h2><blockquote><p>JPEG 压缩是有损压缩，但这个损失的部分是人的视觉不容易察觉到的部分，它充分利用了人眼对计算机色彩中的高频信息部分不敏感的特点，来大大节省了需要处理的数据信息。</p></blockquote><p>人眼对构成图像的不同频率成分具有不同的敏感度，这个是由人眼的视觉生理特性所决定的。如人的眼睛含有对亮度敏感的柱状细胞1.8亿个，含有对色彩敏感的椎状细胞0.08亿个，由于柱状细胞的数量远大于椎状细胞，所以眼睛对亮度的敏感程度要大于对色彩的敏感程度。</p><p>总体来说，一个原始图像信息，要对其进行 JPEG 编码，过程分两大步：</p><ul><li><p>（1）去除视觉上的多余信息，即空间冗余度。</p></li><li><p>（2）去除数据本身的多余信息，即结构（静态）冗余度。</p></li></ul><h3 id="_1-去除视觉上的多余信息" tabindex="-1">1. 去除视觉上的多余信息 <a class="header-anchor" href="#_1-去除视觉上的多余信息" aria-label="Permalink to &quot;1. 去除视觉上的多余信息&quot;">​</a></h3><p>当我们拿到一个原始未经处理的图像，是由各种色彩组成的，即在一个平面上，有各种色彩，而这个平面是由水平和垂直方向上的很多点组成的。实际上，每个点的色彩，也即计算机能表示的每个像素点的色彩，能分解成红、绿、蓝，即 RGB 三元色来表示，即这三种颜色的一定比例的混合就能得到一个实际的色彩值。</p><img src="'+s+'" alt="img"><p>所以，实际上，这个平面的图像，可以理解为除了水平 X 和垂直 Y 以外，还有一个色彩值的 Z 的三维的系统。Z 代表了三元色中各个分支 R/G/B 的混合时所占的具体数值大小，每个像素的 RGB 的混合值可能都有所不同，各个值有大有小，但临近的两个点的 R/G/B 三个值会比较接近。</p><img src="'+l+'" alt="img"><p>由于这个原始图像是由很多个独立的像素点组成的，也就是说它们都是分散的，离散的。比如有些图像的尺寸为640X480，就表示水平有640个像素点，垂直有480个像素点。</p><p>从上面的内容，我们可以知道两个相邻的点，会有很多的色彩是很接近的，那么如何能在最后得到的图片中，尽量少得记录这些不需要的数据，也即达到了压缩的效果。这个就要涉及到图像信号的频谱特性了。</p><p>图像信号的频谱线一般在0-6MHz范围内，而且一幅图像内，包含了各种频率的分量。但包含的大多数为低频频谱线，只在占图像区域比例很低的图像边缘的信号中才含有高频的谱线。这个是对 JPEG 图像压缩的理论依据。</p><p>因此具体的方法就是，在对图像做数字处理时，可根据频谱因素分配比特数：对包含信息量大的低频谱区域分配较多的比特数，对包含信息量低的高频谱区域分配较少的比特数，而图像质量并没有可察觉的损伤，达到数据压缩的目的。</p><p>将原始图像这个色彩空间域，转换为频谱域，怎么转呢？这个就用到了数学上的离散余弦变换，即 <strong>DCT（Discrete Cosine Transform） 变换</strong>。</p><p>DCT 是可逆的、离散的正交变换。变换过程本身虽然并不产生压缩作用，但是变换后的频率系数却非常有利于码率压缩。即这个变换过程得到一个 DCT 变换系数，而对这个系数可以再进行更进一步的处理，即所谓的量化。经过量化，就能达到数据压缩的作用了。</p><p>总体说来，这第一步，对图像进行编码，去除多余的信息，要用到 DCT 变换中的正向 DCT（FDCT），然后再对变换的系数做量化（Quantization），这个过程就是依据的经验值，来处理人眼视觉系统所不敏感的高频数据，从而极大地减少了需要处理的数据量，这个是结合数学方法与经验值而做的处理。</p><h3 id="_2-去除数据本身的多余信息" tabindex="-1">2. 去除数据本身的多余信息 <a class="header-anchor" href="#_2-去除数据本身的多余信息" aria-label="Permalink to &quot;2. 去除数据本身的多余信息&quot;">​</a></h3><p>利用 Huffman 编码，来将最后的数据用无损的方式做压缩，这个是纯数学上的处理方式。</p><h3 id="_3-总结" tabindex="-1">3. 总结 <a class="header-anchor" href="#_3-总结" aria-label="Permalink to &quot;3. 总结&quot;">​</a></h3><p>总体来说，上面的两步即：</p><p>如果处理的是彩色图像，JPEG 算法首先将 RGB 分量转化成亮度分量和色差分量，同时丢失一半的色彩信息（空间分辨率减半）。然后，用 DCT 来进行块变换编码，舍弃高频的系数，并对余下的系数进行量化以进一步减小数据量。最后，使用 RLE 行程编码和 Huffman 编码来完成压缩任务。</p><blockquote><p>参考资料：</p><p><a href="https://jpeg.org/jpeg/index.html" target="_blank" rel="noreferrer">JPEG - JPEG 1</a></p></blockquote>',51)])])}const P=a(E,[["render",p]]);export{f as __pageData,P as default};
